package ai.interviewiq.api.service;
import ai.interviewiq.api.dto.AnalyticsDtos.*; import ai.interviewiq.api.entity.*; import ai.interviewiq.api.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class AnalyticsService { private final InterviewSessionRepository sessions; private final InterviewFeedbackRepository feedbacks; public AnalyticsService(InterviewSessionRepository s,InterviewFeedbackRepository f){sessions=s;feedbacks=f;} @Transactional(readOnly=true) public OverviewResponse overview(Long userId){List<InterviewSession> all=sessions.findByUserId(userId,org.springframework.data.domain.Pageable.unpaged()).getContent();List<InterviewSession> completed=all.stream().filter(x->x.getStatus()==InterviewStatus.COMPLETED).toList();List<Double> scores=completed.stream().map(x->feedbacks.findByInterviewSessionId(x.getId()).map(InterviewFeedback::getOverallScore).orElse(null)).filter(Objects::nonNull).toList();Double avg=scores.isEmpty()?null:scores.stream().mapToDouble(Double::doubleValue).average().orElseThrow();Double best=scores.isEmpty()?null:scores.stream().mapToDouble(Double::doubleValue).max().orElseThrow();List<TrendPoint> trend=completed.stream().map(x->new TrendPoint(x.getId(),String.valueOf(x.getCompletedAt()),feedbacks.findByInterviewSessionId(x.getId()).map(InterviewFeedback::getOverallScore).orElse(null))).filter(x->x.score()!=null).toList();return new OverviewResponse(all.size(),completed.size(),avg,best,avg,avg,avg,trend);} }
